1	/**
2	 * MCP-Native Synchronous Wrapper
3	 * 
4	 * Solves the async mismatch between Gravito's job-based architecture and MCP's request-response model.
5	 * 
6	 * Problem:
7	 * - Gravito returns async job IDs for long-running operations
8	 * - MCP clients expect synchronous responses
9	 * - Poll URLs require separate auth and are unretrievable via MCP
10	 * 
11	 * Solution:
12	 * - Auto-resolve tools under 20s (wait for completion)
13	 * - Return 202 with job_id + poll_url only for truly long-running jobs (>20s estimated)
14	 * - Remove need for external curl polling
15	 * 
16	 * Built with Claude Opus 4 + Gravito governance architecture.
17	 */
18	
19	import { createLogger } from '../_core/logger';
20	import {
21	  createAsyncJob,
22	  markRunning,
23	  completeAsyncJob,
24	  failAsyncJob,
25	  getJob,
26	  getEstimatedDuration,
27	  type AsyncJob,
28	  type CreateJobOptions,
29	} from './async-job-queue';
30	import { executeTool, type ToolExecutionOptions } from './tool-executor';
31	
32	const log = createLogger('mcp-sync-wrapper');
33	
34	// ============================================================================
35	// CONFIGURATION
36	// ============================================================================
37	
38	const SYNC_THRESHOLD_MS = 20_000; // 20 seconds
39	const POLL_INTERVAL_MS = 500;     // 500ms between polls
40	
41	// ============================================================================
42	// TYPES
43	// ============================================================================
44	
45	export interface MCPGovernedCallOptions {
46	  toolName: string;
47	  payload: Record<string, unknown>;
48	  jobOptions: CreateJobOptions;
49	  correlationId?: string;
50	}
51	
52	export interface MCPGovernedCallResult {
53	  /** True if the result is synchronous (completed within threshold) */
54	  sync: boolean;
55	  /** The actual result data (if sync) */
56	  data?: unknown;
57	  /** Job ID (if async) */
58	  jobId?: string;
59	  /** Poll URL (if async) */
60	  pollUrl?: string;
61	  /** Estimated duration in ms (if async) */
62	  estimatedDurationMs?: number;
63	  /** Elapsed time in ms */
64	  elapsedMs: number;
65	}
66	
67	// ============================================================================
68	// CORE API
69	// ============================================================================
70	
71	/**
72	 * Execute a tool with MCP-native sync/async resolution.
73	 * 
74	 * If the tool completes within SYNC_THRESHOLD_MS, returns the result synchronously.
75	 * Otherwise, returns a 202-style response with job_id and poll_url.
76	 */
77	export async function mcpGovernedCall(
78	  options: MCPGovernedCallOptions
79	): Promise<MCPGovernedCallResult> {
80	  const { toolName, payload, jobOptions, correlationId } = options;
81	  const startTime = Date.now();
82	
83	  // Check estimated duration
84	  const estimatedDuration = getEstimatedDuration(toolName);
85	
86	  // If estimated duration is under threshold, try synchronous execution
87	  if (estimatedDuration < SYNC_THRESHOLD_MS) {
88	    try {
89	      log.info(`[${correlationId}] Attempting sync execution for ${toolName} (estimated: ${estimatedDuration}ms)`);
90	      
91	      const result = await executeTool(toolName, payload, {
92	        apiKey: jobOptions.apiKey,
93	        clientIp: jobOptions.clientIp,
94	        userAgent: jobOptions.userAgent,
95	        correlationId,
96	      } as ToolExecutionOptions);
97	
98	      const elapsedMs = Date.now() - startTime;
99	      log.info(`[${correlationId}] Sync execution completed in ${elapsedMs}ms`);
100	
101	      return {
102	        sync: true,
103	        data: result,
104	        elapsedMs,
105	      };
106	    } catch (err) {
107	      // If sync execution fails, fall through to async mode
108	      log.warn(`[${correlationId}] Sync execution failed, falling back to async: ${err}`);
109	    }
110	  }
111	
112	  // Create async job
113	  log.info(`[${correlationId}] Creating async job for ${toolName} (estimated: ${estimatedDuration}ms)`);
114	  
115	  const job = createAsyncJob(toolName, payload, jobOptions);
116	  
117	  // Start execution in background
118	  executeAsyncJob(job, correlationId).catch(err => {
119	    log.error(`[${correlationId}] Async job execution failed: ${err}`);
120	    failAsyncJob(job.id, String(err));
121	  });
122	
123	  // Wait for up to SYNC_THRESHOLD_MS for completion
124	  const completedJob = await waitForJobCompletion(job.id, SYNC_THRESHOLD_MS);
125	
126	  const elapsedMs = Date.now() - startTime;
127	
128	  if (completedJob && completedJob.status === 'completed') {
129	    log.info(`[${correlationId}] Async job completed within threshold (${elapsedMs}ms)`);
130	    return {
131	      sync: true,
132	      data: completedJob.result,
133	      elapsedMs,
134	    };
135	  }
136	
137	  // Job is still running, return async response
138	  log.info(`[${correlationId}] Job still running after ${elapsedMs}ms, returning async response`);
139	  
140	  return {
141	    sync: false,
142	    jobId: job.id,
143	    pollUrl: `/api/mcp/jobs/${job.id}`,
144	    estimatedDurationMs: estimatedDuration,
145	    elapsedMs,
146	  };
147	}
148	
149	/**
150	 * Execute an async job in the background
151	 */
152	async function executeAsyncJob(job: AsyncJob, correlationId?: string): Promise<void> {
153	  try {
154	    markRunning(job.id);
155	    
156	    const result = await executeTool(job.toolName, job.args, {
157	      apiKey: job.apiKey,
158	      clientIp: job.clientIp,
159	      userAgent: job.userAgent,
160	      correlationId,
161	    } as ToolExecutionOptions);
162	
163	    completeAsyncJob(job.id, result);
164	  } catch (err) {
165	    failAsyncJob(job.id, String(err));
166	  }
167	}
168	
169	/**
170	 * Wait for a job to complete, polling at POLL_INTERVAL_MS
171	 */
172	async function waitForJobCompletion(
173	  jobId: string,
174	  timeoutMs: number
175	): Promise<AsyncJob | null> {
176	  const startTime = Date.now();
177	
178	  while (Date.now() - startTime < timeoutMs) {
179	    const job = getJob(jobId);
180	    
181	    if (!job) {
182	      return null;
183	    }
184	
185	    if (job.status === 'completed' || job.status === 'failed') {
186	      return job;
187	    }
188	
189	    // Wait before next poll
190	    await new Promise(resolve => setTimeout(resolve, POLL_INTERVAL_MS));
191	  }
192	
193	  return null;
194	}
195	
196	// ============================================================================
197	// EXPORTS
198	// ============================================================================
199	
200	export const MCPSyncWrapper = {
201	  mcpGovernedCall,
202	  SYNC_THRESHOLD_MS,
203	};
