1027	        return { status: 'schema_override', schema };
1028	      }
1029	      return { status: 'content_passthrough', schema: { type: 'object', properties: { content: { type: 'string' } }, required: ['content'] } };
1030	    };
1031	
1032	    const report: {
1033	      version: string;
1034	      timestamp: string;
1035	      total_tools: number;
1036	      summary: Record<string, number>;
1037	      categories: Record<string, { count: number; tools: unknown[]; total_uncategorized?: number }>;
