1047	    for (const [cat, toolNames] of Object.entries(TOOL_CATEGORIES)) {
1048	      if (filterCategory && cat !== filterCategory) continue;
1049	      const tools = toolNames.map(name => {
1050	        const health = getToolHealth(name);
1051	        report.summary[health.status] = (report.summary[health.status] || 0) + 1;
1052	        return {
1053	          name: `gravito.${name}`,
1054	          status: health.status,
1055	          ...(includeSchemas && health.schema ? { inputSchema: health.schema } : {}),
1056	          description: BRIDGE_TOOL_SCHEMAS[name]?.description || ALL_TOOLS.find(t => t.name === `gravito.${name}`)?.description || '',
