1070	    report.usage_guide = {
1071	      functional: 'These tools have explicit handlers and work reliably.',
1072	      schema_override: 'These tools route through the bridge but have correct schemas.',
1073	      content_passthrough: 'These tools accept a content:string field and route through the reviewer tRPC router.',
1074	      recommendation: 'Start with governance and messaging tools for content review.',
