1358	const TOOL_DISPATCH: Record<string, ToolHandler> = {
1359	  ...governanceTools,
1360	  ...complianceTools,
1361	  ...outboundTools,
1362	  ...financeTools,
1363	  ...agentRuntimeTools,
1364	  ...creativeTools,
1365	  ...workflowTools,
1366	  ...breakGlassTools,
1367	  ...enforcementTools,
1368	  ...narrativeTools,
1369	  ...digestibilityTools,
1370	  ...intelligenceTools,
1371	  ...routingTools,
1372	  ...memoryTools,
1373	  ...hitlTools,
1374	  ...identityTools,
1375	  ...economicTools,
1376	  ...intentTools,
1377	  ...continuityIdentityTools,
1378	  ...continuityMemoryTools,
1379	  ...continuitySelfModelTools,
1380	  ...continuityOutcomeTools,
1381	  ...continuityInternalStateTools,
1382	  ...metaTools,
1383	  ...controlPlaneTools,
1384	  ...surfaceGovernanceTools,
1385	  ...directDispatchTools,
1386	  ...enhancedToolHandlers,
1387	};
1388	
1389	// ============================================================================
1390	// PUBLIC API
1391	// ============================================================================
1392	
1393	/**
1394	 * Execute a Gravito MCP tool by name.
1395	 * 
1396	 * Looks up the tool in the dispatch table first, then falls back to the
1397	 * unified tool bridge for any remaining tools.
1398	 */
1399	export async function executeTool(
1400	  toolName: string,
1401	  args: Record<string, unknown>,
1402	  ctx: ExecutionContext = {},
1403	): Promise<MCPContent> {
1404	  const startTime = Date.now();
1405	  // Strip gravito. prefix for dispatch lookup
1406	  const shortName = toolName.replace('gravito.', '');
1407	
1408	  // ── CONTROL PLANE GATE: Every MCP tool call goes through enforce() ──
1409	  try {
1410	    const { enforce: cpEnforce, getEnforcementMode } = await import('../control-plane');
1411	    const cpResult = await cpEnforce({
1412	      agentId: ctx.userId || 'mcp-caller',
1413	      action: `mcp:${shortName}`,
1414	      content: JSON.stringify(args).slice(0, 500),
1415	      surface: 'mcp',
1416	      riskScore: 0.3,
1417	      metadata: { toolName: shortName, callerType: 'mcp' },
1418	    });
1419	    const cpMode = getEnforcementMode();
1420	    generalLog.info(`[ToolExecutor:ControlPlane:${cpMode}] ${shortName} — ${cpResult.allowed ? 'ALLOWED' : 'BLOCKED'}: ${cpResult.reason}`);
1421	    if (cpResult.blocked && (cpMode === 'hard' || cpMode === 'soft')) {
1422	      generalLog.warn(`[ToolExecutor:ControlPlane] BLOCKED tool ${shortName} in ${cpMode} mode: ${cpResult.reason}`);
1423	      return mcpText({ error: `Control plane ${cpMode}-blocked: ${cpResult.reason}`, blocked: true });
1424	    }
1425	  } catch (cpErr) {
1426	    generalLog.warn(`[ToolExecutor:ControlPlane] Error (non-fatal): ${String(cpErr)}`);
1427	  }
1428	
1429	  // ── Trust Boundary: Validate & coerce input before dispatch ──
1430	  const validationError = validateToolInput(shortName, args || {});
1431	  if (validationError) {
1432	    generalLog.warn(`[ToolExecutor] Validation failed for ${shortName}:`, validationError.error);
1433	    try { const { recordExecution } = await import('./tool-latency-tracker'); recordExecution(shortName, Date.now() - startTime, false); } catch {}
1434	    return mcpText(validationError);
1435	  }
1436	  const coercedArgs = coerceToolInput(shortName, args || {});
1437	
1438	  let success = true;
1439	  try {
1440	    // Check dispatch table first
1441	    const handler = TOOL_DISPATCH[shortName];
1442	    if (handler) {
1443	      return await safeTool(() => handler(coercedArgs, ctx), shortName);
1444	    }
1445	
1446	    // Fallback: route through unified tool bridge
1447	    return await safeTool(async () => {
1448	      const bridge = getUnifiedToolBridge();
1449	      const bridgeResult = await bridge.invokeTool(shortName, coercedArgs || {});
1450	      return mcpText(bridgeResult);
1451	    });
1452	  } catch (err) {
1453	    success = false;
1454	    throw err;
1455	  } finally {
1456	    try { const { recordExecution } = await import('./tool-latency-tracker'); recordExecution(shortName, Date.now() - startTime, success); } catch {}
1457	  }
1458	}
1459	
1460	/** Check if a tool has an explicit handler (not bridge passthrough) */
1461	export function hasExplicitHandler(toolName: string): boolean {
1462	  const shortName = toolName.replace('gravito.', '');
1463	  return shortName in TOOL_DISPATCH;
1464	}
1465	
1466	/** Get all registered tool handler names */
1467	export function getRegisteredHandlers(): string[] {
1468	  return Object.keys(TOOL_DISPATCH);
1469	}
1470

