/**
 * MCP Tool Executor
 * 
 * Dispatch table replacing 82 case statements from the monolithic handler.
 * Each tool maps to a handler function that returns MCP-formatted content.
 * 
 * Pattern:
 *   toolName → async (args, context) => { content: [{ type: 'text', text: string }] }
 */

import { createLogger, type GravitoLogger } from '../_core/logger';
import {
  getGravitoMCPServer,
  getUnifiedToolBridge,
  getCreativePartnerService,
  BRIDGE_TOOL_SCHEMAS,
  TOOL_CATEGORIES,
  EXPLICIT_HANDLER_TOOLS,
  ALL_TOOLS,
} from './tool-registry';

import {
  reviewTradingThesis,
  reviewTradeProposal,
  reviewStrategyChange,
  trackTradingOutcome,
  checkApprovedClaims,
  enforceDisclaimers,
  detectForbiddenLanguage,
  validateCitations,
  exportAuditTrail,
  reviewSequence,
  checkPersonalization,
  enforceBrandVoice,
  trackReplyRate,
  validateToolCall,
  detectPromptInjection,
  enforceEscalation,
  routeModel,
} from './tool-registry';

import {
  getEnforcementStats,
  getEnforcementLog,
  preReleaseGate,
  duringCreationCheck,
} from '../governance/mandatory-enforcement';

import { governedInvokeLLM } from '../governance/mandatory-enforcement';
import { isFeatureEnabled } from '../emotional-geometry-runtime/feature-flags';
import type { GovernedGenerateParams } from '../governance/governed-generate';
import { validateStructuralIntegrity, validateStructuralIntegritySync, type StructuralIntegrityResult } from '../governance/structural-integrity-validator';
import '../governance/adapters/index'; // Auto-register all structural integrity surface adapters

import {
  auditGravitoWebsite,
  auditWebsiteRoutes,
  auditDocsDirectory,
  quickCoherenceCheck,
  WebsiteAdapter,
  DocsAdapter,
  GenericAdapter,
  type ContentUnit,
} from '../governance/narrative-coherence';

import {
  runDigestibilityAudit,
  auditGravitoDigestibility,
  getLatestDigestibilityAudit,
  getDigestibilityHistory,
  detectStructuralAntiPatterns,
} from '../governance/content-digestibility';

import { recordDigestibilitySnapshot } from '../governance/digestibility-trend';

import {
  calculateContentIntelligence,
  runFullContentIntelligenceAudit,
} from '../governance/content-intelligence';

import { mcpError, mcpSuccess, classifyError, type MCPErrorCode } from './mcp-error-contract';
import { validateToolInput, coerceToolInput } from './tool-input-validator';
import {
  optimizeModelRoute as routingSelectModel,
  benchmarkModels as routingOptimizeCost,
  simulateRouting as routingOrchestrateChain,
  getRoutingAnalytics as routingGetDashboard,
} from '../agent/mcp/domains/routing';
import {
  storeMemory as memoryStoreMemory,
  recallMemory as memoryRecallMemories,
  getPersonaState as memoryGetPersonaState,
  updatePersonaState as memoryConsolidateMemories,
  getKnowledgeGraph as memoryGetKnowledgeGraph,
} from '../agent/mcp/domains/memory';
import {
  createApprovalRequest as hitlCreateApprovalRequest,
  resolveApproval as hitlProcessApproval,
  getAnnotationPipeline as hitlAnnotateContent,
  getApprovalQueue as hitlGetApprovalQueue,
  assignReviewer as hitlGetCollaborationMetrics,
} from '../agent/mcp/domains/hitl';
import {
  stitchIdentity as identityStitchIdentity,
  getSessionGraph as identityGetSessionGraph,
  getBehavioralIntelligence as identityAnalyzeBehavior,
  getIdentityGraph as identityGetDashboard,
} from '../agent/mcp/domains/identity';
import {
  attributeRevenue as economicAttributeRevenue,
  analyzeCACImpact as economicCalculateCAC,
  correlateLTV as economicPredictLTV,
  optimizePricing as economicOptimizePricing,
  getEconomicDashboard as economicGetDashboard,
} from '../agent/mcp/domains/economic';
import {
  detectConfusion as intentDetectConfusion,
  analyzeDecisionFriction as intentAnalyzeDecisionFriction,
  mapEmotionalCognitive as intentMapEmotionalCognitive,
  predictIntent as intentPredictIntent,
  getIntentDashboard as intentGetDashboard,
} from '../agent/mcp/domains/intent';
// Continuity Engine domains
import {
  persistIdentity as cePersistIdentity,
  recallIdentity as ceRecallIdentity,
  detectIdentityDrift as ceDetectIdentityDrift,
  enforceConsistency as ceEnforceConsistency,
  getIdentityTimeline as ceGetIdentityTimeline,
} from '../agent/mcp/domains/continuity-identity';
import {
  storeDecisionMemory as ceStoreDecisionMemory,
  promoteMemory as cePromoteMemory,
  scoreCoherence as ceScoreCoherence,
  detectContradiction as ceDetectContradiction,
  compressMemory as ceCompressMemory,
} from '../agent/mcp/domains/continuity-memory';
import {
  registerCapability as ceRegisterCapability,
  assessCapability as ceAssessCapability,
  updateReliability as ceUpdateReliability,
  getCapabilityProfile as ceGetCapabilityProfile,
  detectCapabilityDrift as ceDetectCapabilityDrift,
} from '../agent/mcp/domains/continuity-self-model';
import {
  logAction as ceLogAction,
  tagOutcome as ceTagOutcome,
  detectPatterns as ceDetectPatterns,
  refineStrategy as ceRefineStrategy,
  getOutcomeHistory as ceGetOutcomeHistory,
} from '../agent/mcp/domains/continuity-outcomes';
import {
  recordStateSignal as ceRecordStateSignal,
  assessPressure as ceAssessPressure,
  detectConflict as ceDetectConflict,
  getStateTimeline as ceGetStateTimeline,
  calibrateRiskPosture as ceCalibrateRiskPosture,
} from '../agent/mcp/domains/continuity-internal-state';
import { directDispatchTools } from './direct-dispatch-handlers';
import { mcpArgs, unsafeCast } from '../../shared/type-bridge';
import {
  enhancedAnalyzeBehavior,
  enhancedPredictLTV,
  enhancedPredictIntent,
  enhancedReviewArtifact,
  enhancedTrackEvent,
  enhancedGetConversionBlockers,
  enhancedDetectMoment,
  enhancedAnalyzeContent,
} from './enhanced-tools';

const generalLog: GravitoLogger = createLogger('mcp');

// ============================================================================
// TYPES
// ============================================================================

export interface MCPContent {
  content: Array<{ type: string; text: string }>;
}

export interface ExecutionContext {
  apiKey?: string;
  clientIp?: string;
  userAgent?: string;
  /**
   * TRUSTED authenticated tenant, resolved by the HTTP handler from a validated
   * inference credential (provisioned tenant key → org-<id>/user-<id>, spoof-
   * proof). Additive + optional: existing call sites compile unchanged and leave
   * it undefined. It is the ONLY input that can raise the canonical verdict
   * receipt's tenant binding to `authenticated_tenant`.
   */
  authenticatedTenant?: { tenantId: string; source: string };
}

// Tool arguments arrive as parsed JSON from JSON-RPC — untyped at the boundary.
// Each handler validates its own inputs. This is the explicit trust boundary.
type ToolArgs = Record<string, unknown>;
type ToolHandler = (args: ToolArgs, ctx: ExecutionContext) => Promise<MCPContent>;

// ============================================================================
// HELPER: Wrap result in MCP content format
// ============================================================================

function mcpText(data: unknown): MCPContent {
  return { content: [{ type: 'text', text: JSON.stringify(data) }] };
}

/** Safe wrapper — catches errors and returns them as standardized MCP content */
async function safeTool(fn: () => Promise<MCPContent>, toolName?: string): Promise<MCPContent> {
  try {
    return await fn();
  } catch (error: unknown) {
    const message = error instanceof Error ? error.message : String(error);
    const errorCode = classifyError(error);
    generalLog.error(`[ToolExecutor] ${toolName || 'unknown'} error (${errorCode}):`, error);
    return mcpText(mcpError(message || 'Tool execution failed', errorCode, toolName));
  }
}

// ============================================================================
// GOVERNANCE TOOLS
// ============================================================================

const governanceTools: Record<string, ToolHandler> = {
  reviewContent: async (args) => {
    const server = getGravitoMCPServer();
    // Normalize common parameter mismatches from MCP clients
    const normalized = { ...args } as Record<string, unknown>;
    // surface → surface_type
    if (normalized.surface && !normalized.surface_type) {
      normalized.surface_type = normalized.surface;
      delete normalized.surface;
    }
    // Default surface_type to 'marketing' if missing
    if (!normalized.surface_type) normalized.surface_type = 'marketing';
    // Default artifact_type to 'web_copy' if missing (valid: email|message|web_copy|doc|ad_copy)
    if (!normalized.artifact_type) normalized.artifact_type = 'web_copy';
    // Default to 'quick' mode for MCP calls — fast deterministic checks only.
    // Users can explicitly pass mode: 'release_gate' for full analysis.
    if (!normalized.mode) normalized.mode = 'quick';
    const result = await server.reviewContent(normalized as any);
    // Generate an approval_token when content passes review (not blocked)
    // This token can be passed to downstream tools to unlock gated operations
    if (result && typeof result === 'object' && !result.block_release) {
      try {
        const { getFailClosedGate } = await import('./fail-closed-gate');
        const gate = getFailClosedGate();
        const token = gate.createApprovalToken(
          (normalized.surface_type as string) || 'general',
          'reviewContent',
          true,
          [],
          (normalized.policy_preset as string) || 'default',
          false
        );
        (result as Record<string, unknown>).approval_token = token.tokenId;
      } catch (tokenErr) {
        // Non-fatal: proceed without token
      }
    }
    return mcpText(result);
  },

  governanceAudit: async (args) => {
    const server = getGravitoMCPServer();
    return mcpText(await server.runGovernanceAudit(args as any));
  },

  verifyClaim: async (args) => {
    const server = getGravitoMCPServer();
    return mcpText(await server.verifyClaim(args as any));
  },

  checkCompliance: async (args) => {
    const server = getGravitoMCPServer();
    return mcpText(await server.checkCompliance(args as any));
  },

  getDecisionTrace: async (args) => {
    const server = getGravitoMCPServer();
    return mcpText(await server.getDecisionTrace(args as any));
  },

  getCapabilities: async () => {
    const server = getGravitoMCPServer();
    return mcpText(await server.getCapabilities());
  },

  // --- Tools previously only in monolith, now explicit ---

  runGravito: async (args) => {
    const server = getGravitoMCPServer();
    return mcpText(await server.runGravito(args as any));
  },

  buildGate: async (args) => {
    const server = getGravitoMCPServer();
    return mcpText(await server.buildGate(args as any));
  },

  classifyClaims: async (args) => {
    const server = getGravitoMCPServer();
    return mcpText(await server.classifyClaims(args as any));
  },

  requireEvidence: async (args) => {
    const server = getGravitoMCPServer();
    return mcpText(await server.requireEvidence(args as any));
  },

  validateTruthSurface: async (args) => {
    const server = getGravitoMCPServer();
    return mcpText(await server.validateTruthSurface(args as any));
  },

  getNexusOverview: async (args) => {
    const server = getGravitoMCPServer();
    return mcpText(await server.getNexusOverview(args as any));
  },

  getSurfaceMap: async (args) => {
    const server = getGravitoMCPServer();
    return mcpText(await server.getSurfaceMap(args as any));
  },

  recordOutcome: async (args) => {
    const server = getGravitoMCPServer();
    return mcpText(await server.recordOutcome(args as any));
  },

  getRiskHeatmap: async (args) => {
    const server = getGravitoMCPServer();
    return mcpText(await server.getRiskHeatmap(args as any));
  },

  getOutcomeLift: async (args) => {
    const server = getGravitoMCPServer();
    return mcpText(await server.getOutcomeLift(args as any));
  },

  checkStructuralIntegrity: async (args) => {
    const skipClaude = args?.quick === true || args?.skipClaude === true;
    const verbose = args?.verbose !== false;
    const surfaceFilter = args?.surface as string | undefined;

    if (skipClaude) {
      // Fast deterministic scan — uses validateStructuralIntegritySync
      const syncResult = validateStructuralIntegritySync();
      const filteredIssues = surfaceFilter
        ? syncResult.issues.filter(i => i.surface === surfaceFilter)
        : syncResult.issues;

      return mcpText({
        score: syncResult.score,
        totalIssues: syncResult.totalIssues,
        surfaceBreakdown: syncResult.surfaceBreakdown,
        breakdown: syncResult.breakdown,
        issues: filteredIssues,
        validatedAt: new Date().toISOString(),
        adapters: '8 surfaces: website, mcp_registry, api, documentation, messaging, source_code, infrastructure, project_docs',
      });
    }

    // Full Claude-powered analysis
    const result = await validateStructuralIntegrity({ skipClaude: false, verbose });
    const resultRecord = result as unknown as Record<string, unknown>;
    const allIssues = (resultRecord.issues as Array<{ surface?: string }>) || (result as StructuralIntegrityResult).allIssues || [];
    const filteredIssues = surfaceFilter
      ? allIssues.filter((i) => i.surface === surfaceFilter)
      : allIssues;

    return mcpText({
      score: result.overallScore ?? (resultRecord.score as number),
      totalIssues: result.totalIssues,
      surfaceScores: (result as StructuralIntegrityResult).surfaceScores || {},
      surfaceBreakdown: (resultRecord.surfaceBreakdown as unknown as Record<string, unknown>) || {},
      breakdown: (resultRecord.breakdown as unknown as Record<string, unknown>) || {},
      claudeAnalysis: (result as StructuralIntegrityResult).claudeAnalysis,
      issues: filteredIssues,
      validatedAt: (result as StructuralIntegrityResult).validatedAt || new Date().toISOString(),
      adapters: '8 surfaces: website, mcp_registry, api, documentation, messaging, source_code, infrastructure, project_docs',
    });
  },

  remediateStructuralIssues: async (args) => {
    const { runStructuralRemediation } = await import('../governance/structural-auto-remediation');
    const mode = args?.mode === 'apply' ? 'apply' as const : 'dry_run' as const;
    const surfaces = args?.surfaces as string[] | undefined;
    const useClaude = args?.useClaude !== false;
    const result = await runStructuralRemediation({ mode, surfaces, useClaude });
    return mcpText({
      runId: result.runId,
      mode: result.mode,
      totalIssuesScanned: result.totalIssuesScanned,
      counts: result.counts,
      scoreBefore: result.scoreBefore,
      scoreAfter: result.scoreAfter,
      surfaceBreakdown: result.surfaceBreakdown,
      claudeAnalysis: result.claudeAnalysis,
      durationMs: result.durationMs,
      proposals: result.proposals.slice(0, 20).map(p => ({
        id: p.id,
        surface: p.issue.surface,
        category: p.issue.category,
        action: p.action,
        confidence: p.confidence,
        description: p.description,
        status: p.status,
        targetFile: p.targetFile,
      })),
    });
  },

  previewStructuralRemediation: async (args) => {
    const { previewRemediation } = await import('../governance/structural-auto-remediation');
    const surfaces = args?.surfaces as string[] | undefined;
    const result = previewRemediation(surfaces);
    return mcpText(result);
  },

  checkStructuralThresholds: async () => {
    const { checkThresholds } = await import('../governance/structural-integrity-thresholds');
    const result = checkThresholds('manual');
    return mcpText(result);
  },

  getStructuralThresholds: async () => {
    const { getThresholds } = await import('../governance/structural-integrity-thresholds');
    return mcpText(getThresholds());
  },

  updateStructuralThreshold: async (args) => {
    const { updateThreshold } = await import('../governance/structural-integrity-thresholds');
    const surfaceId = args?.surfaceId as string;
    if (!surfaceId) return mcpText({ error: 'surfaceId is required' });
    const updates: Record<string, unknown> = {};
    if (args?.targetScore !== undefined) updates.targetScore = args.targetScore;
    if (args?.severity !== undefined) updates.severity = args.severity;
    if (args?.enabled !== undefined) updates.enabled = args.enabled;
    if (args?.maxIssues !== undefined) updates.maxIssues = args.maxIssues;
    const result = updateThreshold(surfaceId, unsafeCast(updates, "boundary cast"));
    if (!result) return mcpText({ error: `Surface '${surfaceId}' not found` });
    return mcpText({ success: true, threshold: result });
  },

  getStructuralTrend: async (args) => {
    const { getSurfaceTrend } = await import('../governance/structural-integrity-thresholds');
    const surfaceId = args?.surfaceId as string;
    if (!surfaceId) return mcpText({ error: 'surfaceId is required' });
    const lookback = (args?.lookback as number) || 5;
    return mcpText(getSurfaceTrend(surfaceId, lookback));
  },
};

// ============================================================================
// COMPLIANCE PACK TOOLS
// ============================================================================

const complianceTools: Record<string, ToolHandler> = {
  checkApprovedClaims: async (args) => mcpText(await checkApprovedClaims(args as any)),
  enforceDisclaimers: async (args) => mcpText(await enforceDisclaimers(args as any)),
  detectForbiddenLanguage: async (args) => mcpText(await detectForbiddenLanguage(args as any)),
  validateCitations: async (args) => mcpText(await validateCitations(args as any)),
  exportAuditTrail: async (args) => mcpText(await exportAuditTrail(args as any)),
};

// ============================================================================
// OUTBOUND PACK TOOLS
// ============================================================================

const outboundTools: Record<string, ToolHandler> = {
  composeEmail: async (args) => {
    const server = getGravitoMCPServer();
    return mcpText(await server.composeEmail(args as any));
  },
  reviewSequence: async (args) => mcpText(await reviewSequence(args as any)),
  checkPersonalization: async (args) => mcpText(await checkPersonalization(args as any)),
  enforceBrandVoice: async (args) => mcpText(await enforceBrandVoice(args as any)),
  trackReplyRate: async (args) => mcpText(await trackReplyRate(args as any)),
};

// ============================================================================
// FINANCE PACK TOOLS
// ============================================================================

const financeTools: Record<string, ToolHandler> = {
  reviewTradingThesis: async (args) => mcpText(await reviewTradingThesis(args as any)),
  reviewTradeProposal: async (args) => mcpText(await reviewTradeProposal(args as any)),
  reviewStrategyChange: async (args) => mcpText(await reviewStrategyChange(args as any)),
  trackTradingOutcome: async (args) => mcpText(await trackTradingOutcome(args as any)),
};

// ============================================================================
// AGENT RUNTIME PACK TOOLS
// ============================================================================

const agentRuntimeTools: Record<string, ToolHandler> = {
  validateToolCall: async (args) => mcpText(await validateToolCall(args as any)),
  detectPromptInjection: async (args) => mcpText(await detectPromptInjection(args as any)),
  enforceEscalation: async (args) => mcpText(await enforceEscalation(args as any)),
  routeModel: async (args) => mcpText(await routeModel(args as any)),
};

// ============================================================================
// CREATIVE PARTNER TOOLS
// ============================================================================

const creativeTools: Record<string, ToolHandler> = {
  generateArtifact: async (args) => {
    const server = getGravitoMCPServer();
    // Map MCP parameters to server method parameters
    const prompt = args.goal
      ? `${args.goal}${args.audience ? ` for ${args.audience}` : ''}${args.context ? `. Context: ${args.context}` : ''}`
      : args.prompt || 'Generate content';

    // Map creative artifact_types to valid review types
    const creativeToReviewType: Record<string, string> = {
      hero_section: 'web_copy', landing_page: 'web_copy', email_campaign: 'email',
      social_post: 'ad_copy', blog_post: 'doc', whitepaper: 'doc',
      case_study: 'doc', product_description: 'web_copy', ad_copy: 'ad_copy',
    };
    const artifactType = creativeToReviewType[args.artifact_type] || args.artifact_type || 'web_copy';

    return mcpText(await server.generateArtifact({
      prompt,
      artifact_type: artifactType,
      constraints: args.constraints || {},
    }));
  },

  generateVariants: async (args) => {
    const server = getGravitoMCPServer();
    return mcpText(await server.generateVariants(args as any));
  },

  experimentDesign: async (args) => {
    const server = getGravitoMCPServer();
    return mcpText(await server.experimentDesign(args as any));
  },

  compareVariants: async (args) => {
    const server = getGravitoMCPServer();
    return mcpText(await server.compareVariants(args as any));
  },

  structureCreativity: async (args) => {
    const server = getGravitoMCPServer();
    return mcpText(await server.structureCreativity(args as any));
  },

  // Creative integrity tools (perception domain)
  clarifyIntent: async (args) => {
    const server = getGravitoMCPServer();
    return mcpText(await server.clarifyIntent(args as any));
  },

  simulatePerception: async (args) => {
    const server = getGravitoMCPServer();
    return mcpText(await server.simulatePerception(args as any));
  },

  detectAbstraction: async (args) => {
    const server = getGravitoMCPServer();
