const metaTools: Record<string, ToolHandler> = {
  toolHealth: async (args) => {
    const category = args?.category;
    const includeSchemas = args?.includeSchemas !== false;
    const filterCategory = category && category !== 'all' ? category : null;

    type ToolHealthStatus = 'functional' | 'schema_override' | 'content_passthrough';
    const getToolHealth = (toolName: string): { status: ToolHealthStatus; schema: Record<string, unknown> | null } => {
      const shortName = toolName.replace('gravito.', '');
      const hasSchemaOverride = !!BRIDGE_TOOL_SCHEMAS[shortName];
      const schema = hasSchemaOverride ? BRIDGE_TOOL_SCHEMAS[shortName].inputSchema : null;

      if (EXPLICIT_HANDLER_TOOLS.has(shortName)) {
        return { status: 'functional', schema };
      }
      if (hasSchemaOverride) {
        return { status: 'schema_override', schema };
      }
      return { status: 'content_passthrough', schema: { type: 'object', properties: { content: { type: 'string' } }, required: ['content'] } };
    };

    const report: {
      version: string;
      timestamp: string;
      total_tools: number;
      summary: Record<string, number>;
      categories: Record<string, { count: number; tools: unknown[]; total_uncategorized?: number }>;
      usage_guide?: Record<string, string>;
    } = {
      version: '1.0.0',
      timestamp: new Date().toISOString(),
      total_tools: ALL_TOOLS.length,
      summary: { functional: 0, schema_override: 0, content_passthrough: 0 },
      categories: {},
    };

    for (const [cat, toolNames] of Object.entries(TOOL_CATEGORIES)) {
      if (filterCategory && cat !== filterCategory) continue;
      const tools = toolNames.map(name => {
        const health = getToolHealth(name);
        report.summary[health.status] = (report.summary[health.status] || 0) + 1;
        return {
          name: `gravito.${name}`,
          status: health.status,
          ...(includeSchemas && health.schema ? { inputSchema: health.schema } : {}),
          description: BRIDGE_TOOL_SCHEMAS[name]?.description || ALL_TOOLS.find(t => t.name === `gravito.${name}`)?.description || '',
        };
      });
      report.categories[cat] = { count: tools.length, tools };
    }

    if (!filterCategory) {
      const allCategorized = new Set(Object.values(TOOL_CATEGORIES).flat());
      const uncategorized = ALL_TOOLS
        .filter(t => !allCategorized.has(t.name.replace('gravito.', '')))
        .map(t => ({ name: t.name, status: getToolHealth(t.name).status, description: t.description || '' }));
      report.categories.other = { count: uncategorized.length, tools: uncategorized.slice(0, 20), total_uncategorized: uncategorized.length };
    }

    report.usage_guide = {
      functional: 'These tools have explicit handlers and work reliably.',
      schema_override: 'These tools route through the bridge but have correct schemas.',
      content_passthrough: 'These tools accept a content:string field and route through the reviewer tRPC router.',
      recommendation: 'Start with governance and messaging tools for content review.',
    };

    return mcpText(report);
  },

  // ── Tool Self-Governance ──
  toolGovernanceStatus: async () => {
    const { getGovernanceStatus } = await import('./tool-self-governance');
    return mcpText(getGovernanceStatus());
  },

  toolGovernanceRun: async (args) => {
    const { runGovernance } = await import('./tool-self-governance');
    const mode = (args?.mode as 'startup' | 'continuous' | 'claude') || 'continuous';
    const report = await runGovernance(mode);
    return mcpText(report);
  },

  toolQuarantine: async (args) => {
    const { quarantineTool } = await import('./tool-self-governance');
    const toolName = args?.toolName as string;
    if (!toolName) return mcpText({ error: 'toolName is required' });
    quarantineTool(toolName, 'manual');
    return mcpText({ quarantined: toolName, status: 'success' });
  },

  toolRestore: async (args) => {
