      agentId: (args.agentId as string) || 'unknown',
      action: (args.action as string) || 'unknown',
      content: (args.content as string) || '',
      capability: args.capability as string | undefined,
      tokensRequested: args.tokensRequested as number | undefined,
    });
    return mcpText(result);
  },

  'controlPlane.setMode': async (args) => {
    const cp = await import('../control-plane');
    const mode = args.mode as 'observe' | 'alert' | 'soft' | 'hard';
    const reason = (args.reason as string) || 'MCP tool call';
    const initiatedBy = (args.initiatedBy as string) || 'mcp-caller';
    if (!mode) return mcpText({ error: 'mode is required (observe/alert/soft/hard)' });
    const result = cp.setMode(mode, reason, initiatedBy);
    return mcpText(result);
  },

  'controlPlane.killSwitch': async (args) => {
    const cp = await import('../control-plane');
    const action = args.action as string;
    if (action === 'activate') {
      const target = args.target as any;
      const targetId = (args.targetId as string) || 'global';
      const level = (args.level as any) || 'hard_stop';
      const reason = (args.reason as string) || 'MCP kill switch activation';
      const ttlMs = args.ttlMs as number | undefined;
      const sw = cp.activateKillSwitch(target, targetId, level, reason, 'mcp-caller', ttlMs);
      return mcpText({ success: true, switch: sw });
    } else if (action === 'deactivate') {
      const switchId = args.switchId as string;
      if (!switchId) return mcpText({ error: 'switchId is required for deactivate' });
      const deactivated = cp.deactivateKillSwitch(switchId);
      return mcpText({ success: deactivated, switchId });
    } else if (action === 'list') {
      const active = cp.listActiveKillSwitches();
      return mcpText({ activeSwitches: active });
    }
    return mcpText({ error: 'action must be activate, deactivate, or list' });
  },

  'controlPlane.auditTrail': async (args) => {
    const cp = await import('../control-plane');
    const filter: Record<string, unknown> = {};
    if (args.type) filter.type = args.type;
    if (args.agentId) filter.agentId = args.agentId;
    const entries = cp.getLedgerEntries(Object.keys(filter).length > 0 ? filter as any : undefined);
    const limit = (args.limit as number) || 50;
    const limited = entries.slice(-limit);
    const result: any = { entries: limited, total: entries.length, returned: limited.length };
    if (args.verifyIntegrity) {
      result.integrity = cp.verifyLedgerIntegrity();
    }
    return mcpText(result);
  },

  'controlPlane.configureRedline': async (args) => {
    const cp = await import('../control-plane');
    const id = args.id as string;
    if (!id) return mcpText({ error: 'id is required' });
    const redline = {
      id,
      name: (args.name as string) || id,
      description: (args.description as string) || '',
      severity: (args.severity as any) || 'medium',
      patterns: (args.patterns as string[]) || [],
      action: (args.action as any) || 'warn',
      enabled: (args.enabled as boolean) ?? true,
    };
    cp.setRedline(redline);
    return mcpText({ success: true, redline });
  },
};

// ============================================================================
// UNIFIED DISPATCH TABLE
// ============================================================================

// ============================================================================
// SURFACE GOVERNANCE TOOLS
// ============================================================================

const surfaceGovernanceTools: Record<string, ToolHandler> = {
  'surfaceGovernance.scan': async () => {
    const sg = await import('../surface-governance');
    const result = await sg.scanSurface();
    return json({
      scanId: result.scanId,
      timestamp: result.timestamp,
      summary: result.summary,
      findingCount: result.findings.length,
      findings: result.findings.map(f => ({
        id: f.id,
        rule: f.rule,
        severity: f.severity,
        title: f.title,
        description: f.description,
        file: f.file,
        autoFixable: f.autoFixable,
      })),
    });
  },
  'surfaceGovernance.status': async () => {
    const sg = await import('../surface-governance');
    return json(sg.getSurfaceGovernanceStatus());
  },
  'surfaceGovernance.getRules': async (args) => {
    const sg = await import('../surface-governance');
    const rules = args.enabledOnly ? sg.getEnabledRules() : sg.getRules();
    return json(rules);
  },
  'surfaceGovernance.configureRule': async (args) => {
    const sg = await import('../surface-governance');
    const { ruleId, action, severity } = args as { ruleId: string; action: string; severity?: string };
    switch (action) {
      case 'enable': sg.enableRule(ruleId); break;
      case 'disable': sg.disableRule(ruleId); break;
      case 'updateSeverity': if (severity) sg.updateRuleSeverity(ruleId, severity as any); break;
    }
    return json({ success: true, ruleId, action });
  },
  'surfaceGovernance.planRemediation': async () => {
    const sg = await import('../surface-governance');
    const plan = sg.planRemediation();
    if (!plan) return json({ error: 'No scan results available. Run surfaceGovernance.scan first.' });
    return json({
      scanId: plan.scanId,
      summary: plan.summary,
      findings: plan.findings.map(f => ({
        findingId: f.findingId,
        rule: f.rule,
        severity: f.severity,
        title: f.title,
        status: f.status,
        hasPatch: !!f.patch,
      })),
    });
  },
  'surfaceGovernance.applyFixes': async (args) => {
    const sg = await import('../surface-governance');
    const plan = sg.applyAllFixes({ dryRun: !!args.dryRun });
    if (!plan) return json({ error: 'No remediation plan available. Run surfaceGovernance.planRemediation first.' });
    return json({
      summary: plan.summary,
      results: plan.findings.map(f => ({
        findingId: f.findingId,
        title: f.title,
        status: f.status,
        error: f.error,
      })),
    });
  },
  'surfaceGovernance.applySingleFix': async (args) => {
    const sg = await import('../surface-governance');
    const plan = sg.applySingleFix(args.findingId as string);
    if (!plan) return json({ error: 'No remediation plan available.' });
    const item = plan.findings.find(f => f.findingId === args.findingId);
    return json({ findingId: args.findingId, status: item?.status, error: item?.error });
  },
  'surfaceGovernance.getScanHistory': async () => {
    const sg = await import('../surface-governance');
    return json(sg.getScanHistory());
  },
};

