  analyzeContent: async (args) => mcpText(await enhancedAnalyzeContent(args as Record<string, unknown>)),
};

const TOOL_DISPATCH: Record<string, ToolHandler> = {
  ...governanceTools,
  ...complianceTools,
  ...outboundTools,
  ...financeTools,
  ...agentRuntimeTools,
  ...creativeTools,
  ...workflowTools,
  ...breakGlassTools,
