  checkStructuralIntegrity: async (args) => {
    const skipClaude = args?.quick === true || args?.skipClaude === true;
    const verbose = args?.verbose !== false;
    const surfaceFilter = args?.surface as string | undefined;

    if (skipClaude) {
      // Fast deterministic scan — uses validateStructuralIntegritySync
      const syncResult = validateStructuralIntegritySync();
      const filteredIssues = surfaceFilter
        ? syncResult.issues.filter(i => i.surface === surfaceFilter)
        : syncResult.issues;

      return mcpText({
        score: syncResult.score,
        totalIssues: syncResult.totalIssues,
        surfaceBreakdown: syncResult.surfaceBreakdown,
        breakdown: syncResult.breakdown,
        issues: filteredIssues,
        validatedAt: new Date().toISOString(),
        adapters: '8 surfaces: website, mcp_registry, api, documentation, messaging, source_code, infrastructure, project_docs',
      });
    }

    // Full Claude-powered analysis
    const result = await validateStructuralIntegrity({ skipClaude: false, verbose });
    const resultRecord = result as unknown as Record<string, unknown>;
    const allIssues = (resultRecord.issues as Array<{ surface?: string }>) || (result as StructuralIntegrityResult).allIssues || [];
    const filteredIssues = surfaceFilter
      ? allIssues.filter((i) => i.surface === surfaceFilter)
      : allIssues;

    return mcpText({
      score: result.overallScore ?? (resultRecord.score as number),
      totalIssues: result.totalIssues,
      surfaceScores: (result as StructuralIntegrityResult).surfaceScores || {},
      surfaceBreakdown: (resultRecord.surfaceBreakdown as unknown as Record<string, unknown>) || {},
      breakdown: (resultRecord.breakdown as unknown as Record<string, unknown>) || {},
      claudeAnalysis: (result as StructuralIntegrityResult).claudeAnalysis,
      issues: filteredIssues,
      validatedAt: (result as StructuralIntegrityResult).validatedAt || new Date().toISOString(),
      adapters: '8 surfaces: website, mcp_registry, api, documentation, messaging, source_code, infrastructure, project_docs',
    });
  },

  remediateStructuralIssues: async (args) => {
    const { runStructuralRemediation } = await import('../governance/structural-auto-remediation');
    const mode = args?.mode === 'apply' ? 'apply' as const : 'dry_run' as const;
    const surfaces = args?.surfaces as string[] | undefined;
    const useClaude = args?.useClaude !== false;
    const result = await runStructuralRemediation({ mode, surfaces, useClaude });
    return mcpText({
      runId: result.runId,
      mode: result.mode,
      totalIssuesScanned: result.totalIssuesScanned,
      counts: result.counts,
      scoreBefore: result.scoreBefore,
      scoreAfter: result.scoreAfter,
      surfaceBreakdown: result.surfaceBreakdown,
      claudeAnalysis: result.claudeAnalysis,
      durationMs: result.durationMs,
      proposals: result.proposals.slice(0, 20).map(p => ({
        id: p.id,
        surface: p.issue.surface,
        category: p.issue.category,
        action: p.action,
        confidence: p.confidence,
        description: p.description,
        status: p.status,
        targetFile: p.targetFile,
      })),
    });
  },

  previewStructuralRemediation: async (args) => {
    const { previewRemediation } = await import('../governance/structural-auto-remediation');
    const surfaces = args?.surfaces as string[] | undefined;
    const result = previewRemediation(surfaces);
    return mcpText(result);
  },

  checkStructuralThresholds: async () => {
    const { checkThresholds } = await import('../governance/structural-integrity-thresholds');
    const result = checkThresholds('manual');
    return mcpText(result);
  },

  getStructuralThresholds: async () => {
    const { getThresholds } = await import('../governance/structural-integrity-thresholds');
    return mcpText(getThresholds());
  },

  updateStructuralThreshold: async (args) => {
    const { updateThreshold } = await import('../governance/structural-integrity-thresholds');
    const surfaceId = args?.surfaceId as string;
    if (!surfaceId) return mcpText({ error: 'surfaceId is required' });
    const updates: Record<string, unknown> = {};
    if (args?.targetScore !== undefined) updates.targetScore = args.targetScore;
    if (args?.severity !== undefined) updates.severity = args.severity;
    if (args?.enabled !== undefined) updates.enabled = args.enabled;
    if (args?.maxIssues !== undefined) updates.maxIssues = args.maxIssues;
    const result = updateThreshold(surfaceId, unsafeCast(updates, "boundary cast"));
    if (!result) return mcpText({ error: `Surface '${surfaceId}' not found` });
    return mcpText({ success: true, threshold: result });
  },

  getStructuralTrend: async (args) => {
    const { getSurfaceTrend } = await import('../governance/structural-integrity-thresholds');
    const surfaceId = args?.surfaceId as string;
    if (!surfaceId) return mcpText({ error: 'surfaceId is required' });
    const lookback = (args?.lookback as number) || 5;
    return mcpText(getSurfaceTrend(surfaceId, lookback));
  },
};

