/**
 * MCP-Native Synchronous Wrapper
 * 
 * Solves the async mismatch between Gravito's job-based architecture and MCP's request-response model.
 * 
 * Problem:
 * - Gravito returns async job IDs for long-running operations
 * - MCP clients expect synchronous responses
 * - Poll URLs require separate auth and are unretrievable via MCP
 * 
 * Solution:
 * - Auto-resolve tools under 20s (wait for completion)
 * - Return 202 with job_id + poll_url only for truly long-running jobs (>20s estimated)
 * - Remove need for external curl polling
 * 
 * Built with Claude Opus 4 + Gravito governance architecture.
 */

import { createLogger } from '../_core/logger';
import {
  createAsyncJob,
  markRunning,
  completeAsyncJob,
  failAsyncJob,
  getJob,
  getEstimatedDuration,
  type AsyncJob,
  type CreateJobOptions,
} from './async-job-queue';
import { executeTool, type ToolExecutionOptions } from './tool-executor';

const log = createLogger('mcp-sync-wrapper');

// ============================================================================
// CONFIGURATION
// ============================================================================

const SYNC_THRESHOLD_MS = 20_000; // 20 seconds
const POLL_INTERVAL_MS = 500;     // 500ms between polls

// ============================================================================
// TYPES
// ============================================================================

export interface MCPGovernedCallOptions {
  toolName: string;
  payload: Record<string, unknown>;
  jobOptions: CreateJobOptions;
  correlationId?: string;
}

export interface MCPGovernedCallResult {
  /** True if the result is synchronous (completed within threshold) */
  sync: boolean;
  /** The actual result data (if sync) */
  data?: unknown;
  /** Job ID (if async) */
  jobId?: string;
  /** Poll URL (if async) */
  pollUrl?: string;
  /** Estimated duration in ms (if async) */
  estimatedDurationMs?: number;
  /** Elapsed time in ms */
  elapsedMs: number;
}

// ============================================================================
// CORE API
// ============================================================================

/**
 * Execute a tool with MCP-native sync/async resolution.
 * 
 * If the tool completes within SYNC_THRESHOLD_MS, returns the result synchronously.
 * Otherwise, returns a 202-style response with job_id and poll_url.
 */
export async function mcpGovernedCall(
  options: MCPGovernedCallOptions
): Promise<MCPGovernedCallResult> {
  const { toolName, payload, jobOptions, correlationId } = options;
  const startTime = Date.now();

  // Check estimated duration
  const estimatedDuration = getEstimatedDuration(toolName);

  // If estimated duration is under threshold, try synchronous execution
  if (estimatedDuration < SYNC_THRESHOLD_MS) {
    try {
      log.info(`[${correlationId}] Attempting sync execution for ${toolName} (estimated: ${estimatedDuration}ms)`);

      const result = await executeTool(toolName, payload, {
        apiKey: jobOptions.apiKey,
        clientIp: jobOptions.clientIp,
        userAgent: jobOptions.userAgent,
        correlationId,
      } as ToolExecutionOptions);

      const elapsedMs = Date.now() - startTime;
      log.info(`[${correlationId}] Sync execution completed in ${elapsedMs}ms`);

      return {
        sync: true,
        data: result,
        elapsedMs,
      };
    } catch (err) {
      // If sync execution fails, fall through to async mode
      log.warn(`[${correlationId}] Sync execution failed, falling back to async: ${err}`);
    }
  }

  // Create async job
  log.info(`[${correlationId}] Creating async job for ${toolName} (estimated: ${estimatedDuration}ms)`);

  const job = createAsyncJob(toolName, payload, jobOptions);

  // Start execution in background
  executeAsyncJob(job, correlationId).catch(err => {
    log.error(`[${correlationId}] Async job execution failed: ${err}`);
    failAsyncJob(job.id, String(err));
  });

  // Wait for up to SYNC_THRESHOLD_MS for completion
  const completedJob = await waitForJobCompletion(job.id, SYNC_THRESHOLD_MS);

  const elapsedMs = Date.now() - startTime;

  if (completedJob && completedJob.status === 'completed') {
    log.info(`[${correlationId}] Async job completed within threshold (${elapsedMs}ms)`);
    return {
      sync: true,
      data: completedJob.result,
      elapsedMs,
    };
  }

  // Job is still running, return async response
  log.info(`[${correlationId}] Job still running after ${elapsedMs}ms, returning async response`);

  return {
    sync: false,
    jobId: job.id,
    pollUrl: `/api/mcp/jobs/${job.id}`,
    estimatedDurationMs: estimatedDuration,
    elapsedMs,
  };
}

/**
 * Execute an async job in the background
 */
async function executeAsyncJob(job: AsyncJob, correlationId?: string): Promise<void> {
  try {
    markRunning(job.id);

    const result = await executeTool(job.toolName, job.args, {
      apiKey: job.apiKey,
      clientIp: job.clientIp,
      userAgent: job.userAgent,
      correlationId,
    } as ToolExecutionOptions);

    completeAsyncJob(job.id, result);
  } catch (err) {
    failAsyncJob(job.id, String(err));
  }
}

/**
 * Wait for a job to complete, polling at POLL_INTERVAL_MS
 */
async function waitForJobCompletion(
  jobId: string,
  timeoutMs: number
): Promise<AsyncJob | null> {
  const startTime = Date.now();

  while (Date.now() - startTime < timeoutMs) {
    const job = getJob(jobId);

    if (!job) {
      return null;
    }

    if (job.status === 'completed' || job.status === 'failed') {
      return job;
    }

    // Wait before next poll
    await new Promise(resolve => setTimeout(resolve, POLL_INTERVAL_MS));
  }

  return null;
}

// ============================================================================
// EXPORTS
// ============================================================================

export const MCPSyncWrapper = {
  mcpGovernedCall,
  SYNC_THRESHOLD_MS,
};

