// ============================================================================
// TYPES
// ============================================================================

export interface MCPContent {
  content: Array<{ type: string; text: string }>;
}

export interface ExecutionContext {
  apiKey?: string;
  clientIp?: string;
  userAgent?: string;
  /**
   * Correlation id threaded from the transport boundary so a tool execution can
   * be tied back to the request (or the async job) that started it. Optional:
   * call sites that have no correlation to propagate leave it undefined.
   */
  correlationId?: string;
  /**
   * TRUSTED authenticated tenant, resolved by the HTTP handler from a validated
   * inference credential (provisioned tenant key → org-<id>/user-<id>, spoof-
   * proof). Additive + optional: existing call sites compile unchanged and leave
   * it undefined. It is the ONLY input that can raise the canonical verdict
   * receipt's tenant binding to `authenticated_tenant`.
   */
  authenticatedTenant?: { tenantId: string; source: string };
}

// Tool arguments arrive as parsed JSON from JSON-RPC — untyped at the boundary.
// Each handler validates its own inputs. This is the explicit trust boundary.
type ToolArgs = Record<string, unknown>;
type ToolHandler = (args: ToolArgs, ctx: ExecutionContext) => Promise<MCPContent>;

// ============================================================================
// HELPER: Wrap result in MCP content format
// ============================================================================

function mcpText(data: unknown): MCPContent {
  return { content: [{ type: 'text', text: JSON.stringify(data) }] };
}

/** Safe wrapper — catches errors and returns them as standardized MCP content */
async function safeTool(fn: () => Promise<MCPContent>, toolName?: string): Promise<MCPContent> {
  try {
    return await fn();
  } catch (error: unknown) {
    const message = error instanceof Error ? error.message : String(error);
    const errorCode = classifyError(error);
    generalLog.error(`[ToolExecutor] ${toolName || 'unknown'} error (${errorCode}):`, error);
    return mcpText(mcpError(message || 'Tool execution failed', errorCode, toolName));
  }
}

