  checkContentEnforcement: async (args) => {
    const checkResult = await duringCreationCheck(args?.content || '', args?.contentType || 'general');
    return mcpText(checkResult);
  },

  governedGenerate: async (args, ctx) => {
    const prompt = args?.prompt || 'Generate content';
    const contentType = args?.contentType || 'general';
    const systemPrompt = args?.systemPrompt || 'You are a professional content writer. Generate clear, accurate, and compliant content.';

    // The legacy governedInvokeLLM path — the exact behavior shipped today.
    // FLAG-OFF returns this verbatim (BYTE-IDENTICAL); the FLAG-ON branch also
    // falls back to it if the canonical pipeline throws (the receipt must NEVER
    // break the tool).
    const runLegacyGovernedInvoke = async (): Promise<MCPContent> => {
      const llmParams = {
        messages: [
          { role: 'system' as const, content: systemPrompt },
          { role: 'user' as const, content: prompt },
        ],
      };
      const genResult = await governedInvokeLLM(llmParams, contentType);
      const generatedContent = genResult?.choices?.[0]?.message?.content || 'Generation completed but no content returned';
      return mcpText({
        generated_content: generatedContent,
        content_type: contentType,
        governance_applied: true,
        gravito_run_id: `gen_${Date.now()}_${Math.random().toString(36).substr(2, 9)}`,
      });
    };

    // FLAG-OFF (default): byte-identical legacy path. No canonical routing runs.
    if (!isFeatureEnabled('CANONICAL_VERDICT_RECEIPT_ENABLED')) {
      return runLegacyGovernedInvoke();
    }

    // FLAG-ON: route through the canonical governedGenerate pipeline (carrying
    // the TRUSTED tenant the handler resolved), then ADAPT the result back into
    // the existing MCP response shape — the four legacy keys are preserved and
    // decision/score/modified/issues/canonical_receipt are added ADDITIVELY
    // (canonical_receipt is undefined unless the flag+derivation produced one,
    // in which case JSON.stringify omits it).
    try {
      const { governedGenerate: canonicalGovernedGenerate } = await import('../governance/governed-generate');
      const params: GovernedGenerateParams = {
        messages: [{ role: 'user' as const, content: typeof prompt === 'string' ? prompt : String(prompt) }],
        systemPrompt: typeof systemPrompt === 'string' ? systemPrompt : String(systemPrompt),
        contentType: typeof contentType === 'string' ? contentType : String(contentType),
        contentRole:
          typeof args?.content_role === 'string'
            ? (args.content_role as GovernedGenerateParams['contentRole'])
            : 'user-facing',
        audienceType:
          typeof args?.audience_type === 'string'
            ? (args.audience_type as GovernedGenerateParams['audienceType'])
            : 'general',
        productId: typeof args?.product_id === 'string' ? args.product_id : undefined,
        productName: typeof args?.product_name === 'string' ? args.product_name : undefined,
        surfaceId: typeof args?.surface_id === 'string' ? args.surface_id : undefined,
        authenticatedTenant: ctx?.authenticatedTenant,
      };
      const genResult = await canonicalGovernedGenerate(params);
      return mcpText({
        generated_content: genResult.content,
        content_type: contentType,
        governance_applied: genResult.governed,
        gravito_run_id: genResult.gravito_run_id ?? `gen_${Date.now()}_${Math.random().toString(36).substr(2, 9)}`,
        decision: genResult.decision,
        score: genResult.score,
        modified: genResult.modified,
        issues: genResult.issues,
        canonical_receipt: genResult.canonical_receipt,
      });
    } catch (err) {
      generalLog.warn(`[ToolExecutor] governedGenerate canonical path failed — falling back to legacy path:`, err);
      return runLegacyGovernedInvoke();
    }
  },
};

