    const policies = cp.getAllPolicies();
    const redlines = cp.getAllRedlines();
    return mcpText({
      ...status,
      policies: policies.map(p => ({ agentId: p.agentId, name: p.name, enabled: p.enabled, maxAutonomy: p.maxAutonomyLevel })),
      redlines: redlines.map(r => ({ id: r.id, name: r.name, severity: r.severity, action: r.action, enabled: r.enabled })),
